const input = ($input.first() && $input.first().json) ? $input.first().json : {};
const store = $getWorkflowStaticData("global");
if (typeof store.dailyPreviewBatchIndex !== "number") store.dailyPreviewBatchIndex = 0;
store.dailyPreviewBatchIndex += 1;

const facts = Array.isArray(input.news_facts) && input.news_facts.length ? input.news_facts : [];
const fallback = {
  fact: "4월 24일부터 합성니코틴 액상형 전자담배도 ‘담배’로 묶였다.",
  jab: "어제까진 애매하다더니 오늘부턴 금연구역 규제까지 같이 온다.",
  question: "이게 질서 정리야, 아니면 늦게 온 뒷북이야?",
  link: "https://www.korea.kr/news/policyNewsView.do?newsId=148959006",
  title: "합성니코틴 액상형 전자담배 규제",
  source_mode: "fallback_verified"
};
const getFact = (idx) => facts[idx % facts.length] || fallback;

const batchDate = new Date(new Date().toLocaleString("en-US", { timeZone: "Asia/Seoul" }));
const dateKey = `${batchDate.getFullYear()}-${String(batchDate.getMonth()+1).padStart(2,'0')}-${String(batchDate.getDate()).padStart(2,'0')}`;
const executionSeed = `${Date.now().toString(36)}-${store.dailyPreviewBatchIndex}`;
const batchId = `${dateKey}-${executionSeed}`;
const recentIndex = Array.isArray(store.generated_content_index) ? store.generated_content_index : [];
const recentCutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
const recentMemory = recentIndex
  .filter(r => new Date(r.created_at || 0).getTime() >= recentCutoff)
  .slice(-20)
  .map(r => ({ hook: String(r.hook_first_line || "").trim(), post_type: String(r.post_type || ""), angle: String(r.angle || ""), cta_style: String(r.cta_style || "") }));
const recent_hooks = recentMemory.map(r => r.hook).filter(Boolean);
const recent_angles = recentMemory.map(r => r.angle).filter(Boolean);
const recent_cta_styles = recentMemory.map(r => r.cta_style).filter(Boolean);

const slots = [
  { post_type: "feed", label: "FEED", slot: "feed_2100", publish_time: "21:00", factIndex: 0, angle: "deep_analysis", hook_style: "hidden_cost", cta_style: "forced_choice" },
  { post_type: "reel", label: "REEL 1", slot: "reel_1200", publish_time: "12:00", factIndex: 1, angle: "loss_emotion", hook_style: "you_are_losing", cta_style: "save_or_get_burned" },
  { post_type: "carousel", label: "CAROUSEL 1", slot: "carousel_1205", publish_time: "12:05", linked_reel_slot: "reel_1200", factIndex: 1, angle: "comparison", hook_style: "surface_vs_reality", cta_style: "which_side" },
  { post_type: "reel", label: "REEL 2", slot: "reel_1800", publish_time: "18:00", factIndex: 2, angle: "absurd_comedy", hook_style: "this_is_ridiculous", cta_style: "tag_someone" },
  { post_type: "carousel", label: "CAROUSEL 2", slot: "carousel_1805", publish_time: "18:05", linked_reel_slot: "reel_1800", factIndex: 2, angle: "checklist", hook_style: "check_before_buying", cta_style: "save_checklist" },
  { post_type: "reel", label: "REEL 3", slot: "reel_2200", publish_time: "22:00", factIndex: 3, angle: "debate_trigger", hook_style: "agree_or_disagree", cta_style: "comment_side" },
  { post_type: "carousel", label: "CAROUSEL 3", slot: "carousel_2205", publish_time: "22:05", linked_reel_slot: "reel_2200", factIndex: 3, angle: "hidden_structure", hook_style: "who_benefits", cta_style: "dm_if_you_see_it" }
];

const visualStyles = [
  "ABSURD_NEWSROOM",
  "WALLET_MONSTER",
  "CCTV_CHAOS",
  "COURTROOM_CARTOON",
  "STREET_INTERVIEW",
  "FINE_STAMP_MONSTER",
  "COMMENT_WAR_SPLITSCREEN"
];
const mediaPrompts = {
  ABSURD_NEWSROOM: "absurd Korean breaking-news comedy about vape regulation, adult-only, no readable text, no brands, confused vape device wearing a tiny suit at a news desk, giant fine stamp, cartoon regulation cloud, meme-like but cinematic",
  WALLET_MONSTER: "hilarious wallet monster comedy about vape regulation, adult-only, no readable text, no logos, price tag monster eating a wallet, shopper panic, absurd Korean internet meme energy",
  CCTV_CHAOS: "fake CCTV documentary chaos about vape regulation, adult-only, no readable text, gritty overhead store view, shelf maze, clerk shrugging, cartoon overlays",
  COURTROOM_CARTOON: "surreal courtroom cartoon about vape regulation, adult-only, no readable text, vape bottle on witness stand, calendar April 24, angry wallet defendant",
  STREET_INTERVIEW: "chaotic Korean street interview comedy about vape regulation, adult-only, no readable text, exaggerated shocked adult faces, yes or no debate energy",
  FINE_STAMP_MONSTER: "absurd fine stamp monster chasing adult shopper, vape regulation news, no readable text, no logos, funny uncomfortable meme realism",
  DUALITY_POSTER: "symbolic editorial poster about the duality of the world, adult-only, no readable text, no logos, outwardly clean safe regulation mask on the front, behind it hidden receipts, fines, confused consumers, split mirror composition, A on the surface but B underneath, cinematic high contrast",
  COMMENT_WAR_SPLITSCREEN: "split screen comment war visual, adults debating vape regulation yes or no, cartoon speech bubbles without readable text, high contrast comedy"
};



// PSYCHOLOGICAL DIVERSITY ENGINE v3
const psychHookTypes = [
  { key: "loss_trigger", label: "Loss Trigger", open: "이거 모르면 계속 돈 날립니다" },
  { key: "identity_threat", label: "Identity Threat", open: "이 방식 쓰는 사람들, 거의 다 잘못 알고 있습니다" },
  { key: "pattern_break", label: "Pattern Break", open: "다들 가격 보는데, 이게 먼저입니다" },
  { key: "regret_projection", label: "Regret Projection", open: "이거 안 보면 다음 달에 후회합니다" },
  { key: "hidden_knowledge", label: "Hidden Knowledge", open: "이건 업자들은 알고 소비자는 모릅니다" },
  { key: "contrarian_truth", label: "Contrarian Truth", open: "싸다고 좋은 게 아니라, 이게 문제입니다" },
  { key: "question_trap", label: "Question Trap", open: "왜 같은 걸 사도 돈이 더 나갈까요?" },
  { key: "time_pressure", label: "Time Pressure", open: "지금 바뀌는 구조, 늦으면 바로 손해입니다" }
];
const psychAngles = ["비용 착각", "선택 순서 오류", "규제 충격", "소비자 심리 착각", "매장 vs 소비자 정보 차이", "타이밍 실패", "반복 구매 패턴"];
const psychToneMix = ["cold_authority", "cold_authority", "cold_authority", "cold_authority", "warning", "warning", "warning", "subtle_accusation", "subtle_accusation", "curiosity"];
const visualScenes = ["매장", "집", "거리", "계산대", "손 클로즈업"];
const visualEmotions = ["당황", "짜증", "혼란", "의심", "후회"];
const visualRenderStyles = ["현실 사진", "과장된 상징", "만화 스타일", "광고 패러디 느낌"];
const visualObjects = ["제품", "가격표", "영수증", "손", "비교 장면"];

function pickRotated(list, idx, salt, previous) {
  let offset = Math.abs(String(salt || '').split('').reduce((a, c) => a + c.charCodeAt(0), 0));
  let picked = list[(idx + offset) % list.length];
  if (previous && (picked.key || picked) === previous) picked = list[(idx + offset + 1) % list.length];
  return picked;
}

function visualCombo(idx, seed) {
  const salt = Math.abs(String(seed || '').split('').reduce((a, c) => a + c.charCodeAt(0), 0));
  return {
    scene: visualScenes[(idx + salt) % visualScenes.length],
    emotion: visualEmotions[(idx * 2 + salt) % visualEmotions.length],
    render_style: visualRenderStyles[(idx * 3 + salt) % visualRenderStyles.length],
    object: visualObjects[(idx * 4 + salt) % visualObjects.length]
  };
}

function compactFact(f) {
  return String(f.fact || '').replace(/\s+/g, ' ').trim();
}

function buildPsychPost(f, slot, idx, seed) {
  const hookType = pickRotated(psychHookTypes, idx, seed, store.last_psych_hook_type || "");
  const dominantAngle = slot.psych_angle_override || pickRotated(psychAngles, idx, `${seed}_${slot.post_type}`, "");
  const tone = pickRotated(psychToneMix, idx, `${seed}_${dominantAngle}`, "");
  const visual = visualCombo(idx, `${seed}_${dominantAngle}_${hookType.key}`);
  const factLine = compactFact(f);
  const jab = String(f.jab || '').replace(/\s+/g, ' ').trim();
  const question = String(f.question || '').replace(/\s+/g, ' ').trim();
  const opener = `${hookType.open}. ${factLine}`;
  const discomfort = `${dominantAngle}에서 제일 불편한 건 이겁니다. ${jab || '사람들은 제품을 고른다고 생각하지만 실제로는 정보 차이 안에서 움직입니다.'}`;
  const realization = `아... 이거네. 문제는 취향이 아니라, 누가 먼저 구조를 알고 들어가느냐입니다.`;
  const fear = `이걸 놓치면 다음 구매에서 돈, 시간, 선택권 중 하나는 조용히 새나갑니다.`;
  const pressure = question && question.endsWith('?') ? question : `저장해두고 볼래요, 아니면 또 매장 앞에서 감으로 고를래요?`;
  return {
    hookType,
    dominantAngle,
    tone,
    visual,
    hookLine: opener,
    caption: [opener, discomfort, realization, fear, pressure].join('\n'),
    mediaPrompt: `${visual.scene}, ${visual.emotion}, ${visual.render_style}, ${visual.object}, behavioral psychology tension, pattern disruption, adult consumer regret, funny but uncomfortable, scroll-stopping, no readable text, no logos, no minors, no smoking glamor, based on verified Korean news fact: ${factLine}`
  };
}


const angleOpeners = {
  loss_emotion: (f) => `${f.fact} 이거 모르면 돈보다 먼저 판단력이 털린다.`,
  absurd_comedy: (f) => `${f.fact} 근데 현장은 거의 코미디처럼 굴러간다.`,
  debate_trigger: (f) => `${f.fact} 이건 보호냐, 뒷북 단속이냐부터 갈린다.`,
  comparison: (f) => `${f.fact} 겉보기엔 정리, 실제론 선택지 축소다.`,
  checklist: (f) => `${f.fact} 매장 가기 전에 이것부터 확인해라.`,
  hidden_structure: (f) => `${f.fact} 누가 먼저 알고 움직였는지 봐야 한다.`,
  deep_analysis: (f) => `${f.fact} 이 뉴스는 그냥 넘기면 손해다.`
};
const angleClosers = {
  loss_emotion: "너 이거 그냥 넘길 거야, 아니면 다음 계산대 앞에서 덜 당할 거야?",
  absurd_comedy: "이게 진짜 소비자 보호로 보여, 아니면 규제 코미디로 보여?",
  debate_trigger: "너는 이거 찬성이야, 아니면 말만 보호인 뒷북이라고 봐?",
  comparison: "겉말과 실제 현장 중에 너는 어느 쪽을 믿을 거야?",
  checklist: "이 체크리스트 저장할래, 아니면 또 매장 앞에서 물어볼래?",
  hidden_structure: "이 구조 보이면 댓글 달고, 안 보이면 그냥 지나가도 된다.",
  deep_analysis: "너라면 이걸 소비자 보호라고 보냐, 아니면 늦게 온 단속 장치라고 보냐?"
};
function applyAngleCaption(baseCaption, f, angle) {
  const lines = String(baseCaption || '').split('\n').filter(Boolean);
  const opener = (angleOpeners[angle] || angleOpeners.loss_emotion)(f);
  const closer = angleClosers[angle] || f.question;
  if (lines.length) lines[0] = opener;
  if (lines.length > 1) lines[lines.length - 1] = closer;
  return lines.join('\n');
}

const reelCaption = (f) => [
  f.fact,
  f.jab,
  `팩트만 보면 더 불편하다. 4월 24일 이후 합성니코틴 전담은 더 이상 애매한 회색지대가 아니다. 금연구역, 광고 제한, 건강경고, 판매 방식까지 한 번에 묶이면 제일 늦게 맞는 건 늘 소비자다. 매장은 바뀐 룰을 알고 움직이는데, 손님은 예전 감각으로 들어간다. 그 차이에서 돈이 새고, 과태료가 생기고, 이상한 추천도 먹힌다.`,
  `여기서 웃긴 건 다들 “보호”라는 말만 반복한다는 거다. 보호라면 왜 사람들은 매장 앞에서야 알까. 보호라면 왜 가격표와 안내문은 바뀌는데 설명은 항상 늦을까. 이 채널에서 보는 건 제품 자랑이 아니라 그 뒤의 구조다. 겉으로는 건강 명분, 뒤로는 비용과 선택권의 재배치다.`,
  `이걸 모르면 다음에 매장 가서도 똑같이 당한다. 표면에는 건강, 안전, 보호 같은 단어가 붙는다. 그런데 실제로는 가격표, 사용 가능 장소, 판매 문구, 추천 순서가 조용히 바뀐다. 사람들은 제품을 고른다고 생각하지만 사실 바뀐 규칙 안에서 남은 선택지를 고르는 거다. 이 차이를 아는 사람은 질문을 다르게 하고, 모르는 사람은 그냥 계산한다. 이거 그냥 규제 강화라고 넘길 거야, 아니면 네 지갑이랑 선택권이 어디서 털리는지 볼 거야?`
].join("\n");
const carouselCaption = (f) => [
  f.fact,
  f.jab,
  `겉으로는 규제 정리처럼 보인다. 그런데 이면을 보면 소비자가 제일 늦게 배우는 게임이다. 매장은 안내문을 바꾸고, 판매 가능 문구를 조절하고, 추천 순서를 바꾼다. 손님은 그냥 평소처럼 들어가서 “왜 갑자기 이게 안 돼?”를 묻는다. 이 차이가 돈이 된다.`,
  `진짜 봐야 할 건 제품이 아니라 기준이다. 금연구역, 과태료, 광고 제한, 건강경고가 한 번에 붙으면 선택은 좁아지고 설명은 어려워진다. 겉으로는 안전한 제도처럼 보이지만, 뒤에서는 누가 먼저 알고 누가 늦게 아는지가 갈린다. 먼저 아는 쪽은 안내문을 바꾸고, 늦게 아는 쪽은 계산대 앞에서 당황한다. 누군가는 보호라고 말하겠지만, 누군가는 이걸 늦게 온 단속이라고 부를 거다.`,
  f.question
].join("\n");
const feedCaption = (f) => {
  const paragraphs = [
    `${f.fact} 이거 그냥 뉴스 제목 하나로 넘기면 손해다. 전자담배 규제는 이제 취향 문제가 아니라, 어디서 피우고, 어떻게 팔고, 어떤 문구를 붙일 수 있는지까지 한 번에 묶이는 문제로 바뀌고 있다. 예전처럼 “전담은 좀 다르지 않나” 하고 넘기면, 실제 현장에서는 금연구역, 과태료, 광고 문구, 매장 안내에서 바로 헷갈린다.`,
    `핵심은 합성니코틴 액상형 전자담배가 기존 담배 규제 바깥에 있던 시간이 끝났다는 거다. 보도와 정책자료 기준으로 4월 24일부터 담배 정의가 니코틴 제품까지 넓어지고, 건강경고 표시, 광고 제한, 금연구역 사용 금지 같은 규칙이 같이 따라온다. 그러니까 이건 단순히 제품 이름이 바뀐 문제가 아니다. 소비자가 어디서 써도 되는지, 매장이 어떻게 설명해야 하는지, 온라인 판매가 어디까지 가능한지까지 연결된다.`,
    `소비자 입장에서는 “작고 냄새 덜 나니까 괜찮겠지”라는 감각이 제일 위험하다. 규제가 바뀌면 단속은 감정이 아니라 기준으로 움직인다. 몰랐다는 말이 통할 수도 있지만, 돈은 보통 모르는 쪽에서 먼저 나간다. 특히 금연구역 과태료나 판매 제한 같은 건 나중에 검색해서 알면 늦다. 이미 계산대 앞이거나, 이미 피웠거나, 이미 잘못 안내받은 뒤일 수 있다.`,
    `더 웃긴 건 이 변화가 갑자기 도덕 문제처럼 포장된다는 점이다. 누군가는 청소년 보호라고 말하고, 누군가는 뒤늦게 만든 땜질 규제라고 말한다. 둘 다 어느 정도 맞을 수 있다. 그런데 정작 중요한 건 소비자가 정확한 기준을 제일 늦게 안다는 거다. 정책은 발표되고, 매장은 바뀌고, 가격표와 안내 문구는 움직이는데, 사용자는 그냥 평소처럼 들어간다.`,
    `그래서 지금 봐야 할 건 찬반보다 기준이다. 4월 24일 이후 합성니코틴 전담이 어떤 규제 안으로 들어갔는지, 금연구역과 광고 제한이 어떻게 붙는지, 매장에서 어떤 말이 달라지는지 확인해야 한다. 너라면 이걸 소비자 보호라고 보냐, 아니면 뒤늦게 만든 단속 장치라고 보냐?`
  ];
  return paragraphs.join("\n\n");
};

const output = slots.map((slot, idx) => {
  const f = getFact(slot.factIndex);
  const id = `${Date.now()}-${idx + 1}-${Math.random().toString(36).slice(2, 7)}`;
  const style = slot.post_type === "feed" ? "DUALITY_POSTER" : visualStyles[idx % visualStyles.length];
  const angleOffset = Math.abs(String(executionSeed || '').split('').reduce((a, c) => a + c.charCodeAt(0), 0)) % psychAngles.length;
  const slotForPsych = { ...slot, psych_angle_override: psychAngles[(idx + angleOffset) % psychAngles.length] };
  const psych = buildPsychPost(f, slotForPsych, idx, executionSeed);
  const caption = psych.caption;
  const variation_seed = `${dateKey}_${executionSeed}_${idx + 1}`;
  const queueAction = `queue_${slot.post_type}`;
  const buttons = [
    [{ text: `Queue ${slot.label}`, callback_data: `${queueAction}|${id}` }],
    [{ text: "Delete", callback_data: `delete_test|${id}` }]
  ];
  if (slot.post_type !== "feed") {
    buttons.splice(1, 0, [{ text: "Regen Text", callback_data: `regen_text|${id}` }]);
    buttons.splice(2, 0, [{ text: "Regen Media", callback_data: `regen_media|${id}` }]);
  }
  return {
    json: {
      simulation_mode: false,
      mode: "daily_preview_phase1",
      batch_id: batchId,
      date_key: dateKey,
      daily_preview_index: idx + 1,
      daily_preview_total: 7,
      post_type: slot.post_type,
      content_slot: slot.slot,
