    const xml = await this.helpers.httpRequest({ method: 'GET', url, timeout: 15000 });
    const items = String(xml || '').match(/<item>[\s\S]*?<\/item>/g) || [];
    for (const raw of items.slice(0, 5)) {
      const pick = (tag) => {
        const m = raw.match(new RegExp('<' + tag + '>([\\s\\S]*?)<\\/' + tag + '>'));
        return m ? m[1].replace(/^<!\[CDATA\[/, '').replace(/\]\]>$/, '').trim() : '';
      };
      const title = pick('title').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&#39;/g, "'");
      const link = pick('link');
      const pubDate = pick('pubDate');
      if (title && link) candidates.push({ query: q, title, link, pubDate });
    }
  } catch (e) {
    // Keep fallback path alive.
  }
}

return [{ json: { news_candidates: candidates, news_fetched_at: new Date().toISOString() } }];

const input = $input.first()?.json || {};
const candidates = Array.isArray(input.news_candidates) ? input.news_candidates : [];
const allowed = /(korea\.kr|pressian\.com|donga\.com|joins\.com|joongang|seoul\.co\.kr|news\.naver\.com|yna\.co\.kr)/i;
