  .map(x => {
    let score = 0;
    const t = String(x.title || '');
    if (/4월\s*24일|24일부터|10만원|37년|벌금|징역|금지|규제|과태료/.test(t)) score += 5;
    if (/논란|금지|벌금|과태료|똑같이|동일/.test(t)) score += 3;
    if (allowed.test(String(x.link || ''))) score += 2;
    return { ...x, score };
  })
  .sort((a,b) => b.score - a.score);

const fallbackFacts = [
