      ? "이 정도면 보호야, 아니면 과한 단속이야?"
      : "이 변화, 납득돼 아니면 뒷북 같아?",
    source_mode: "latest_rss"
  });
}

while (newsFacts.length < 7) {
  const f = fallbackFacts[newsFacts.length % fallbackFacts.length];
  newsFacts.push({ ...f, source_mode: "fallback_verified" });
}

return [{ json: { ...input, news_facts: newsFacts.slice(0, 7), fact_selected_at: new Date().toISOString() } }];

